    "kind": "grammar",
    "es": "¿Te late? ¡Sale!",
    "fr": "Proposer, accepter, refuser",
    "art": "ui-grammar",
    "explanation": "Pour proposer : ¿Vamos a…? ¿Quieres…? ¿Te late…? (très mexicain : ça te dit ?). Pour accepter : ¡Va!, ¡Sale!, ¡Órale!, ¡Claro! Pour refuser poliment : No puedo, tengo que… / Mejor otro día.",
    "examples": [
     {
      "es": "¿Te late ir al cine el viernes?",
      "fr": "Ça te dit d'aller au cinéma vendredi ?"
     },
     {
      "es": "Sale, nos vemos a las ocho.",
      "fr": "Ça marche, on se voit à huit heures."
     }
    ],
